$ErrorActionPreference='Stop';$repo=Split-Path -Parent $PSScriptRoot;$scripts=Join-Path $repo 'local-file-organizer\scripts';$temp=Join-Path ([IO.Path]::GetTempPath()) ('local-file-organizer-test-'+[guid]::NewGuid().ToString('N'))
try{$source=Join-Path $temp 'source';$target=Join-Path $temp 'target';$state=Join-Path $temp 'state';New-Item -ItemType Directory -Path $source,$target -Force|Out-Null;[IO.File]::WriteAllText((Join-Path $source 'a.txt'),'alpha');[IO.File]::WriteAllText((Join-Path $source 'b.txt'),'same');[IO.File]::WriteAllText((Join-Path $target 'b.txt'),'same')
 & (Join-Path $scripts 'Get-LocalFileInventory.ps1') -Root $source -StateDir $state | Out-Null;$inventory=@(Import-Csv (Join-Path $state 'inventory.csv'));if($inventory.Count -ne 2){throw 'Inventory count failed'}
 $plan=Join-Path $temp 'plan.csv';@($inventory|ForEach-Object{[pscustomobject]@{SourcePath=$_.SourcePath;TargetPath=Join-Path $target $_.Name;SizeBytes=$_.SizeBytes;ModifiedUtc=$_.ModifiedUtc}}) | Export-Csv $plan -NoTypeInformation -Encoding utf8
 & (Join-Path $scripts 'Test-LocalFilePlan.ps1') -PlanCsv $plan -ApprovedRoots @($target) | Out-Null;& (Join-Path $scripts 'Start-LocalFileOrganization.ps1') -PlanCsv $plan -StateDir $state -ApprovedRoots @($target) -StopAfterOperations 1 | Out-Null;& (Join-Path $scripts 'Start-LocalFileOrganization.ps1') -PlanCsv $plan -StateDir $state -ApprovedRoots @($target) | Out-Null;$status=& (Join-Path $scripts 'Get-LocalFileOrganizationStatus.ps1') -PlanCsv $plan -StateDir $state | ConvertFrom-Json;if($status.done -ne 2){throw 'Apply/resume count failed'}
 $results=@(Get-Content (Join-Path $state 'results.jsonl')|ForEach-Object{$_|ConvertFrom-Json});if(@($results|Where-Object {$_.status -eq 'duplicate-isolated'}).Count -ne 1){throw 'Duplicate isolation failed'}
 & (Join-Path $scripts 'Restore-LocalFileOrganization.ps1') -PlanCsv $plan -StateDir $state | Out-Null;if((Get-Content (Join-Path $source 'a.txt') -Raw) -ne 'alpha'){throw 'Rollback A failed'};if((Get-Content (Join-Path $source 'b.txt') -Raw) -ne 'same'){throw 'Rollback B failed'};Write-Host 'PASS: local-file-organizer end-to-end'}finally{if(Test-Path $temp){Remove-Item -LiteralPath $temp -Recurse -Force}}
